<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin'});const trash=ref(false);const {data,refresh}=await useFetch('/api/admin/pages',{query:{trash}});const csrf=useCsrf();async function remove(p:{id:string;status:string}){if(p.status==='TRASH')await $fetch(`/api/admin/pages/${p.id}?permanent=true`,{method:'DELETE',headers:csrf.value});else await $fetch(`/api/admin/pages/${p.id}`,{method:'DELETE',headers:csrf.value});await refresh()}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">页面</h1><NuxtLink to="/admin/pages/new" class="rounded-full px-5 py-2 text-white" style="background:var(--accent)">新建页面</NuxtLink></div><label class="mt-4 block text-sm"><input v-model="trash" type="checkbox"> 回收站</label><div class="mt-5 border-t" style="border-color:var(--border)"><div v-for="p in data||[]" :key="p.id" class="flex justify-between border-b py-4" style="border-color:var(--border)"><NuxtLink :to="`/admin/pages/${p.id}`"><strong>{{p.title}}</strong><p class="text-sm" style="color:var(--muted)">/{{p.slug}} · {{p.status}}</p></NuxtLink><button @click="remove(p)">{{p.status==='TRASH'?'永久删除':'移入回收站'}}</button></div></div></div></template>
